struct WeightBufferContext{void*ptr;bool owned;};struct State{ggml_backend_t backend=nullptr;ggml_backend_buffer_t weight_buffer=nullptr,workspace=nullptr;ggml_context*ctx=nullptr;ggml_tensor*w=nullptr,*x=nullptr,*y=nullptr;ggml_cgraph*graph=nullptr;int64_t K=0,N=0;bool destroyed=false;torch::Tensor weight_owner;};static void ck(bool v,const char*m){TORCH_CHECK(v,m);}
static ggml_backend_buffer_t wrap_cuda_ptr(ggml_backend_t b,void*p,size_t n,bool owned){ggml_backend_buffer_i i{};auto*c=new WeightBufferContext{p,owned};i.free_buffer=[](ggml_backend_buffer_t b){auto*c=(WeightBufferContext*)b->context;if(c->owned)cudaFree(c->ptr);delete c;};i.get_base=[](ggml_backend_buffer_t b){return((WeightBufferContext*)b->context)->ptr;};i.init_tensor=[](ggml_backend_buffer_t,ggml_tensor*){return GGML_STATUS_SUCCESS;};i.memset_tensor=[](ggml_backend_buffer_t,ggml_tensor*t,uint8_t v,size_t o,size_t z){cudaMemset((char*)t->data+o,v,z);};i.set_tensor=[](ggml_backend_buffer_t,ggml_tensor*t,const void*d,size_t o,size_t z){cudaMemcpy((char*)t->data+o,d,z,cudaMemcpyHostToDevice);};i.get_tensor=[](ggml_backend_buffer_t,const ggml_tensor*t,void*d,size_t o,size_t z){cudaMemcpy(d,(char*)t->data+o,z,cudaMemcpyDeviceToHost);};i.cpy_tensor=[](ggml_backend_buffer_t,const ggml_tensor*,ggml_tensor*){return false;};i.clear=[](ggml_backend_buffer_t b,uint8_t v){cudaMemset(((WeightBufferContext*)b->context)->ptr,v,b->size);};i.reset=[](ggml_backend_buffer_t){};return ggml_backend_buffer_init(ggml_backend_get_default_buffer_type(b),i,c,n);}
static void destroy_resources(State*s){if(!s||s->destroyed)return;s->destroyed=true;if(s->workspace)ggml_backend_buffer_free(s->workspace);if(s->weight_buffer)ggml_backend_buffer_free(s->weight_buffer);if(s->ctx)ggml_free(s->ctx);if(s->backend)ggml_backend_free(s->backend);s->workspace=nullptr;s->weight_buffer=nullptr;s->ctx=nullptr;s->backend=nullptr;s->w=nullptr;s->x=nullptr;s->y=nullptr;s->graph=nullptr;}
static pybind11::capsule make_state(const torch::Tensor&W,const torch::Tensor&X,bool borrowed){TORCH_CHECK(W.is_cuda()&&W.scalar_type()==torch::kUInt8&&W.dim()==2&&W.is_contiguous(),"expected contiguous CUDA Q4_0");TORCH_CHECK(X.is_cuda()&&X.scalar_type()==torch::kBFloat16&&X.dim()==2&&X.size(0)==32&&X.is_contiguous(),"expected CUDA BF16 M32");TORCH_CHECK(W.device()==X.device(),"device mismatch");auto init_stream=at::cuda::getCurrentCUDAStream(W.get_device()).stream();cudaStreamCaptureStatus init_capture;C10_CUDA_CHECK(cudaStreamIsCapturing(init_stream,&init_capture));TORCH_CHECK(init_capture==cudaStreamCaptureStatusNone,"T004 handle creation attempted during CUDA Graph capture");int64_t K=X.size(1),N=W.size(0);TORCH_CHECK(K%32==0&&W.size(1)==K/32*18,"Q4_0 shape mismatch");auto*s=new State();s->K=K;s->N=N;s->weight_owner=W;try{s->backend=ggml_backend_cuda_init(W.get_device());ck(s->backend,"backend init");auto st=init_stream;ggml_backend_cuda_set_external_stream(s->backend,(void*)st);ggml_init_params ip{1<<20,nullptr,true};s->ctx=ggml_init(ip);s->w=ggml_new_tensor_2d(s->ctx,GGML_TYPE_Q4_0,K,N);s->x=ggml_new_tensor_2d(s->ctx,GGML_TYPE_F32,K,32);s->y=ggml_mul_mat(s->ctx,s->w,s->x);s->graph=ggml_new_graph(s->ctx);ggml_build_forward_expand(s->graph,s->y);size_t nw=ggml_nbytes(s->w),nx=ggml_nbytes(s->x),ny=ggml_nbytes(s->y);void*wp=W.data_ptr();if(!borrowed)C10_CUDA_CHECK(cudaMalloc(&wp,nw));s->weight_buffer=wrap_cuda_ptr(s->backend,wp,nw,!borrowed);s->w->data=wp;s->w->buffer=s->weight_buffer;s->workspace=ggml_backend_alloc_buffer(s->backend,nx+ny+4096);char*p=(char*)ggml_backend_buffer_get_base(s->workspace);ck(ggml_backend_tensor_alloc(s->workspace,s->x,p)==GGML_STATUS_SUCCESS,"input alloc");ck(ggml_backend_tensor_alloc(s->workspace,s->y,p+nx)==GGML_STATUS_SUCCESS,"output alloc");ggml_backend_buffer_set_usage(s->workspace,GGML_BACKEND_BUFFER_USAGE_COMPUTE);if(!borrowed)C10_CUDA_CHECK(cudaMemcpyAsync(wp,W.data_ptr(),nw,cudaMemcpyDeviceToDevice,st));auto xf=X.to(torch::kFloat32).contiguous();C10_CUDA_CHECK(cudaMemcpyAsync(ggml_get_data(s->x),xf.data_ptr(),nx,cudaMemcpyDeviceToDevice,st));C10_CUDA_CHECK(cudaStreamSynchronize(st));return pybind11::capsule(s,"t004.ggml",[](void*p){auto*s=(State*)p;destroy_resources(s);delete s;});}catch(...){destroy_resources(s);delete s;throw;}}
static pybind11::capsule create_borrowed(const torch::Tensor&W,const torch::Tensor&X){return make_state(W,X,true);}static pybind11::capsule create_owned(const torch::Tensor&W,const torch::Tensor&X){return make_state(W,X,false);}static std::vector<uintptr_t>info(pybind11::capsule h){auto*s=(State*)h.get_pointer();return{(uintptr_t)ggml_get_data(s->w),(uintptr_t)ggml_get_data(s->x),(uintptr_t)ggml_get_data(s->y),(uintptr_t)s->backend};}static uintptr_t output_tensor_address(pybind11::capsule h){return(uintptr_t)ggml_get_data(((State*)h.get_pointer())->y);}static void destroy_handle(pybind11::capsule h){auto*s=(State*)h.get_pointer();if(s)destroy_resources(s);}
static void update(pybind11::capsule h,const torch::Tensor&X){auto*s=(State*)h.get_pointer();TORCH_CHECK(s&&X.is_cuda()&&X.scalar_type()==torch::kBFloat16&&X.size(0)==32&&X.size(1)==s->K,"bad input");auto st=at::cuda::getCurrentCUDAStream(X.get_device()).stream();ggml_backend_cuda_set_external_stream(s->backend,(void*)st);auto xf=X.to(torch::kFloat32).contiguous();C10_CUDA_CHECK(cudaMemcpyAsync(ggml_get_data(s->x),xf.data_ptr(),ggml_nbytes(s->x),cudaMemcpyDeviceToDevice,st));}static void update_inplace(pybind11::capsule h,const torch::Tensor&X){auto*s=(State*)h.get_pointer();TORCH_CHECK(s&&X.is_cuda()&&X.scalar_type()==torch::kBFloat16&&X.size(0)==32&&X.size(1)==s->K&&X.is_contiguous(),"bad BF16 M32 input");auto st=at::cuda::getCurrentCUDAStream(X.get_device()).stream();ggml_backend_cuda_set_external_stream(s->backend,(void*)st);auto xf=X.to(torch::kFloat32).contiguous();C10_CUDA_CHECK(cudaMemcpyAsync(ggml_get_data(s->x),xf.data_ptr(),ggml_nbytes(s->x),cudaMemcpyDeviceToDevice,st));}static void run(pybind11::capsule h){auto*s=(State*)h.get_pointer();auto st=at::cuda::getCurrentCUDAStream().stream();ggml_backend_cuda_set_external_stream(s->backend,(void*)st);ck(ggml_backend_graph_compute_async(s->backend,s->graph)==GGML_STATUS_SUCCESS,"async graph compute");}static void prewarm(pybind11::capsule h){auto*s=(State*)h.get_pointer();auto st=at::cuda::getCurrentCUDAStream().stream();ggml_backend_cuda_set_external_stream(s->backend,(void*)st);ck(ggml_backend_graph_compute_async(s->backend,s->graph)==GGML_STATUS_SUCCESS,"prewarm");ggml_backend_synchronize(s->backend);}static uintptr_t graph_capture(pybind11::capsule h){auto*s=(State*)h.get_pointer();auto st=at::cuda::getCurrentCUDAStream().stream();ggml_backend_cuda_set_external_stream(s->backend,(void*)st);cudaStreamCaptureStatus cs;C10_CUDA_CHECK(cudaStreamIsCapturing(st,&cs));TORCH_CHECK(cs==cudaStreamCaptureStatusActive,"not capturing");ck(ggml_backend_graph_compute_async(s->backend,s->graph)==GGML_STATUS_SUCCESS,"capture");cudaGraph_t g;C10_CUDA_CHECK(cudaStreamGetCaptureInfo_v2(st,&cs,nullptr,&g,nullptr,nullptr));return(uintptr_t)g;}static std::vector<int64_t>capture_info(pybind11::capsule){auto st=at::cuda::getCurrentCUDAStream().stream();cudaStreamCaptureStatus cs;unsigned long long id;C10_CUDA_CHECK(cudaStreamIsCapturing(st,&cs));C10_CUDA_CHECK(cudaStreamGetCaptureInfo(st,&cs,&id));return{(int64_t)st,(int64_t)cs,(int64_t)id};}static torch::Tensor readout(pybind11::capsule h){auto*s=(State*)h.get_pointer();auto st=at::cuda::getCurrentCUDAStream().stream();auto y=torch::empty({32,s->N},torch::TensorOptions().device(torch::kCUDA).dtype(torch::kFloat32));C10_CUDA_CHECK(cudaMemcpyAsync(y.data_ptr(),ggml_get_data(s->y),ggml_nbytes(s->y),cudaMemcpyDeviceToDevice,st));C10_CUDA_CHECK(cudaStreamSynchronize(st));return y;}static torch::Tensor output_view(pybind11::capsule h){auto*s=(State*)h.get_pointer();auto opt=torch::TensorOptions().device(torch::kCUDA,s->weight_owner.get_device()).dtype(torch::kFloat32);return torch::from_blob(ggml_get_data(s->y),{32,s->N},[h](void*){},opt);}
PYBIND11_MODULE(TORCH_EXTENSION_NAME,m){m.def("create",&create_owned);m.def("create_borrowed",&create_borrowed);m.def("capture_info",&capture_info);m.def("graph_capture",&graph_capture);m.def("info",&info);m.def("output_tensor_address",&output_tensor_address);m.def("destroy",&destroy_handle);m.def("update",&update);m.def("update_inplace",&update_inplace);m.def("output_view",&output_view);m.def("prewarm",&prewarm);m.def("run",&run);m.def("read_output",&readout);}
